<script setup lang="ts">
import { ref,onMounted,onUnmounted,watch } from 'vue'
import { useRoute } from 'vue-router'
import { Search,RefreshCw,ArrowRight,ScrollText } from 'lucide-vue-next'
import StatusTag from '../components/StatusTag.vue'
import { getRequests,getRequest } from '../api/requests'
import { errorMessage } from '../api/http'
import type { RequestRecord } from '../types'
const route=useRoute(),items=ref<RequestRecord[]>([]),loading=ref(true),error=ref(''),q=ref(String(route.query.q??'')),status=ref(''),page=ref(1),total=ref(0),detail=ref<RequestRecord|null>(null),detailOpen=ref(false),detailLoading=ref(false),detailError=ref('')
const time=(v:string)=>new Date(v).toLocaleString('zh-CN',{hour12:false})
async function load(){loading.value=true;error.value='';try{const result=await getRequests({page:page.value,page_size:10,q:q.value||undefined,status:status.value||undefined});items.value=result.items;total.value=result.total}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
function search(){page.value=1;load()}
async function show(record:RequestRecord){detailOpen.value=true;detailLoading.value=true;detailError.value='';detail.value=null;try{detail.value=await getRequest(record.id)}catch(e){detailError.value=errorMessage(e)}finally{detailLoading.value=false}}
watch(()=>route.query.q,value=>{q.value=String(value??'');search()})
onMounted(()=>{load();window.addEventListener('modelgate:refresh',load)})
onUnmounted(()=>window.removeEventListener('modelgate:refresh',load))
</script>
<template><section class="page-heading"><div><h1 class="page-title">请求日志</h1><p class="page-subtitle">查看每次模型调用，沿着尝试记录定位问题。</p></div><button class="btn btn-secondary" :disabled="loading" @click="load"><RefreshCw :size="15" :class="{'is-spinning':loading}"/>刷新</button></section><section class="panel"><form class="table-toolbar" @submit.prevent="search"><div class="search-input"><Search :size="16"/><input v-model="q" aria-label="搜索请求" placeholder="搜索请求 ID、模型或供应商…"/></div><el-select v-model="status" aria-label="筛选请求状态" class="status-select" @change="search"><el-option value="" label="全部状态"/><el-option value="success" label="成功"/><el-option value="error" label="失败"/></el-select><button class="btn btn-secondary" type="submit">搜索</button><span class="toolbar-count">{{total}} 条请求</span></form><div v-if="error" class="error-state" role="alert">{{error}}<button class="text-link" @click="load">重试</button></div><el-skeleton v-if="loading" :rows="8" animated class="panel-body"/><div v-else class="table-wrap"><table class="data-table logs-table"><thead><tr><th>请求 ID / 时间</th><th>模型</th><th>供应商</th><th>状态</th><th class="align-right">耗时</th><th class="align-right">Token</th><th class="align-right">尝试</th><th></th></tr></thead><tbody><tr v-for="request in items" :key="request.id" @click="show(request)" class="clickable-row"><td><button class="request-id mono" @click.stop="show(request)">{{request.id.slice(0,21)}}</button><small class="table-secondary mono">{{time(request.created_at)}}</small></td><td><span class="model-name">{{request.model}}</span><small class="table-secondary">{{request.is_stream?'SSE 流式':'JSON 响应'}}</small></td><td>{{request.provider||'未分配'}}</td><td><StatusTag :status="request.status"/></td><td class="mono align-right">{{request.latency_ms}}<span class="muted"> ms</span></td><td class="mono align-right">{{(request.input_tokens+request.output_tokens).toLocaleString()}}</td><td class="mono align-right">{{request.attempts.length}}</td><td><ArrowRight :size="15" class="muted"/></td></tr><tr v-if="!items.length"><td colspan="8"><div class="empty-state"><ScrollText :size="28"/><strong>没有找到请求</strong><span>调整搜索条件，或发起一次测试请求。</span></div></td></tr></tbody></table></div><div class="table-pagination"><span class="muted">每页 10 条 · 共 {{total}} 条</span><el-pagination v-model:current-page="page" :page-size="10" :total="total" layout="prev, pager, next" @current-change="load"/></div></section><p class="field-note">日志仅记录元数据与模拟 Token，不保存提示词或完整响应正文。</p><el-drawer v-model="detailOpen" title="请求详情" :size="560"><el-skeleton v-if="detailLoading" :rows="9" animated/><div v-else-if="detailError" class="error-state">{{detailError}}</div><template v-else-if="detail"><div class="detail-status"><StatusTag :status="detail.status"/><span class="subtle-tag">演示请求</span></div><h3 class="detail-section-title">请求信息</h3><dl class="detail-list"><div><dt>请求 ID</dt><dd class="mono">{{detail.id}}</dd></div><div><dt>公开模型</dt><dd class="mono">{{detail.model}}</dd></div><div><dt>创建时间</dt><dd>{{time(detail.created_at)}}</dd></div><div><dt>最终上游</dt><dd>{{detail.provider||'未分配'}}</dd></div><div><dt>状态码 / 总延迟</dt><dd class="mono">{{detail.status_code}} / {{detail.latency_ms}} ms</dd></div><div><dt>输入 / 输出 Token</dt><dd class="mono">{{detail.input_tokens}} / {{detail.output_tokens}}</dd></div></dl><div v-if="detail.error" class="error-state">{{detail.error}}</div><h3 class="detail-section-title">上游尝试 <span class="count-badge">{{detail.attempts.length}}</span></h3><div v-for="(attempt,index) in detail.attempts" :key="index" class="attempt-row"><span class="attempt-number">{{index+1}}</span><div><strong>{{attempt.provider}}</strong><span class="attempt-error">{{attempt.error||'响应成功'}}</span></div><span class="mono" :class="attempt.status_code>=400?'danger-text':'success-text'">{{attempt.status_code}}</span><span class="mono muted">{{attempt.latency_ms}} ms</span></div><div v-if="!detail.attempts.length" class="empty-state">请求未进入上游执行阶段。</div></template></el-drawer></template>
